class C
{
    void M1(C c1)
    {
        int x, y;
        _ = c1?.MA(out x, out y).MB() ?? false
            ? x.ToString()
            : y.ToString(); // 1
    }

    void M2(C c1)
    {
        int x, y;
        _ = c1?.MA(out x, out y)?.MB() ?? false
            ? x.ToString()
            : y.ToString(); // 2
    }

    C MA(out int x, out int y) { x = 42; y = 42; return this; }
    bool MB() { return true; }
}

